import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// One small app, the lab's: the UniFFI Kotlin bindings of OlcrtcRuntime
// (generated by build-core-android.sh into src/main/kotlin) on JNA,
// libghostlane_core.so (src/main/jniLibs) and the instrumented tests. The app's
// versions, the app's packaging (legacy, the libraries extracted), the app's
// minSdk.
plugins {
    // The app's Kotlin (its root build puts the same plugin on the classpath).
    alias(libs.plugins.kotlin.android) apply false
    alias(libs.plugins.android.application)
}

android {
    namespace = "org.ghostlane.lab.rustcore"
    compileSdk = 37

    defaultConfig {
        applicationId = "org.ghostlane.lab.rustcore"
        minSdk = 23
        targetSdk = 37
        versionCode = 1
        versionName = "1"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        ndk {
            // The app's defaultAndroidAbiFilters.
            abiFilters += listOf("armeabi-v7a", "arm64-v8a", "x86_64")
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    // build-ghostlane-core-android.sh's output: -PghostlaneCoreDir=<dir>
    // (jniLibs/<abi>/libghostlane_core.so and kotlin/ with the bindings).
    val coreDir = file(providers.gradleProperty("ghostlaneCoreDir").orElse("../../out/core").get())
    sourceSets.getByName("main") {
        jniLibs.srcDir(coreDir.resolve("jniLibs"))
        java.srcDir(coreDir.resolve("kotlin"))
    }

    packaging {
        jniLibs {
            useLegacyPackaging = true
        }
    }
}

kotlin {
    compilerOptions {
        jvmTarget.set(JvmTarget.JVM_17)
    }
}

dependencies {
    // JNA as an AAR: its libjnidispatch.so for each ABI.
    implementation("net.java.dev.jna:jna:${libs.versions.jna.get()}@aar")
    androidTestImplementation("androidx.test:runner:1.7.0")
    androidTestImplementation("androidx.test.ext:junit:1.3.0")
}
